class Solution:
    def numPairsDivisibleBy60(self, time: list[int]) -> int:
        count = [0] * 60
        res = 0
        for t in time:
            r = t % 60
            res += count[(60 - r) % 60]
            count[r] += 1
        return res

class Solution {
public:
    int numPairsDivisibleBy60(vector<int>& time) {
        vector<int> count(60, 0);
        int res = 0;
        for (int t : time) {
            int r = t % 60;
            res += count[(60 - r) % 60];
            count[r]++;
        }
        return res;
    }
};

